import numpy as np
from scipy.optimize import curve_fit
conv={0:lambda s: float(s.replace(',','.')),1:lambda s: float(s.replace(',','.'))}
d=np.genfromtxt('graphene.dat', delimiter='\t', converters=conv)
x=d[:,0]; y=d[:,1]
s=1e7/x
i=np.argsort(s); s=s[i]; y=y[i]

def lor(x,off,A,x0,gam): # gam FWHM
    return off + A*(gam/2)**2/((x-x0)**2+(gam/2)**2)
def gauss(x,off,A,x0,gam): # gam FWHM
    return off + A*np.exp(-4*np.log(2)*(x-x0)**2/gam**2)
def lorlin(x,off,slope,A,x0,gam):
    return off+slope*(x-x0) + A*(gam/2)**2/((x-x0)**2+(gam/2)**2)
def gausslin(x,off,slope,A,x0,gam):
    return off+slope*(x-x0) + A*np.exp(-4*np.log(2)*(x-x0)**2/gam**2)

regions={'G':[(1480,1680),(1500,1660),(1520,1640),(1450,1720),(1540,1620)],
         '2D':[(2550,2820),(2570,2780),(2500,2850),(2600,2750),(2520,2800)]}
for name,regs in regions.items():
 print('\n====',name)
 for lo,hi in regs:
  m=(s>=lo)&(s<=hi); xx=s[m]; yy=y[m]
  p0=[np.median(yy),np.max(yy)-np.median(yy),xx[np.argmax(yy)],30]
  print('\nwindow',lo,hi,'n',len(xx),'max',xx[np.argmax(yy)],yy.max())
  for f,pn in [(lor,'L'),(gauss,'Gauss')]:
   try:
    popt,pcov=curve_fit(f,xx,yy,p0=p0,maxfev=20000)
    pred=f(xx,*popt); rmse=np.sqrt(np.mean((yy-pred)**2))
    print(f' {pn}: off={popt[0]:.3f} A={popt[1]:.3f} x0={popt[2]:.5f} gamma={popt[3]:.5f} rmse={rmse:.2f}')
   except Exception as e: print(f' {pn} err',e)
  for f,pn in [(lorlin,'Llin'),(gausslin,'Gausslin')]:
   try:
    popt,pcov=curve_fit(f,xx,yy,p0=p0+[0.0],maxfev=20000)
    pred=f(xx,*popt); rmse=np.sqrt(np.mean((yy-pred)**2))
    print(f' {pn}: off={popt[0]:.3f} slope={popt[1]:.4f} A={popt[2]:.3f} x0={popt[3]:.5f} gamma={popt[4]:.5f} rmse={rmse:.2f}')
   except Exception as e: print(f' {pn} err',e)
