from scipy.optimize import curve_fit
conv={0:lambda s: float(s.replace(',','.')),1:lambda s: float(s.replace(',','.'))}
d=np.genfromtxt('graphene.dat', delimiter='\t', converters=conv)
x=d[:,0]; y=d[:,1]
s=1e7/x
i=np.argsort(s); s=s[i]; y=y[i]

def lor(x,off,A,x0,gam): return off + A*(gam/2)**2/((x-x0)**2+(gam/2)**2)
def lorlin(x,off,slope,A,x0,gam): return off+slope*(x-x0)+A*(gam/2)**2/((x-x0)**2+(gam/2)**2)
def gauss(x,off,A,x0,gam): return off+A*np.exp(-4*np.log(2)*(x-x0)**2/gam**2)
def gausslin(x,off,slope,A,x0,gam): return off+slope*(x-x0)+A*np.exp(-4*np.log(2)*(x-x0)**2/gam**2)
def pv(x,off,slope,A,x0,gam,eta):
    return off+slope*(x-x0)+A*(eta*(gam/2)**2/((x-x0)**2+(gam/2)**2)+(1-eta)*np.exp(-4*np.log(2)*(x-x0)**2/gam**2))
regions={'G':[(1450,1720),(1480,1680),(1500,1660),(1520,1640),(1540,1620)],
         '2D':[(2500,2850),(2550,2820),(2570,2780),(2600,2750),(2520,2800)]}
for name,regs in regions.items():
 print('\n====',name)
 for lo,hi in regs:
  m=(s>=lo)&(s<=hi); xx=s[m]; yy=y[m]
  xp=xx[np.argmax(yy)]; yp=yy.max(); med=np.median(yy); A=yp-med
  print('\nwindow',lo,hi,'n',len(xx),'max',xp,yp)
  for f,pn,p0 in [(lor,'L',[med,A,xp,20]),
                  (gauss,'Gauss',[med,A,xp,20]),
                  (lorlin,'Llin',[med,0,A,xp,20]),
                  (gausslin,'Gausslin',[med,0,A,xp,20]),
                  (pv,'PVlin',[med,0,A,xp,20,0.5])]:
   try:
    bounds=([-np.inf,-np.inf,0,lo,0.1] if 'lin' in pn else [-np.inf,0,lo,0.1])
    if pn=='PVlin': bounds=([-np.inf,-np.inf,0,lo,0.1,0],[np.inf,np.inf,np.inf,hi,hi,1])
    if pn=='Llin': bounds=([-np.inf,-np.inf,0,lo,0.1],[np.inf,np.inf,np.inf,hi,hi])
    if pn=='Gausslin': bounds=([-np.inf,-np.inf,0,lo,0.1],[np.inf,np.inf,np.inf,hi,hi])
    popt,pcov=curve_fit(f,xx,yy,p0=p0,bounds=bounds,maxfev=50000)
    pred=f(xx,*popt); rmse=np.sqrt(np.mean((yy-pred)**2))
    print(f' {pn:8s}: off={popt[0]:9.2f} slope={popt[1] if len(popt)>4 else 0:9.3f} A={popt[2] if len(popt)>4 else popt[1]:9.2f} x0={popt[3] if len(popt)>4 else popt[2]:9.4f} gamma={popt[4] if len(popt)>4 else popt[3]:8.4f} eta={popt[5] if len(popt)>5 else 0:6.3f} rmse={rmse:7.2f}')
   except Exception as e: print(f' {pn} err {e}')
